//! Roland GS's variation tones: the Sound Canvas (SC-55) put its other
//! sounds on the same program numbers as GM's, in banks picked by Bank
//! Select MSB (CC 0). These are the SC-55's best-known variations, by
//! its own names; a bank Neumetik doesn't have plays GM's sound, the
//! capital tone, as the SC-55 did.

use super::gm::TABLE;
use super::patch::Lfo;
use super::patch::Patch as P;
use super::patch::Wave::*;

/// A variation of GM's `program`, in bank `msb`.
const fn v(msb: u8, program: u8, patch: P) -> (u8, u8, P) {
    (msb, program, patch)
}

const fn gm(program: usize) -> P {
    TABLE[program]
}

